import { randomBytes } from 'node:crypto';
import { decryptSecret, encryptSecret } from '@/lib/crypto';
import type { StoreKeys } from './store-client';

export interface WooCredentials extends StoreKeys {
  /** Generated by Retzef and given only to the store; used to verify webhook signatures. */
  webhookSecret: string;
}

// A type alias (not an interface) so it is assignable to a Prisma JSON value.
type SealedCredentials = {
  v: 1;
  cipher: string;
  iv: string;
  tag: string;
};

/** Credentials are stored only encrypted (AES-256-GCM with ENCRYPTION_KEY). */
export function sealCredentials(credentials: WooCredentials): SealedCredentials {
  const { cipher, iv, tag } = encryptSecret(credentials);
  return { v: 1, cipher: cipher.toString('base64'), iv: iv.toString('base64'), tag: tag.toString('base64') };
}

export function openCredentials(stored: unknown): WooCredentials | null {
  const sealed = stored as Partial<SealedCredentials> | null;
  if (!sealed || sealed.v !== 1 || !sealed.cipher || !sealed.iv || !sealed.tag) return null;
  const value = decryptSecret(Buffer.from(sealed.cipher, 'base64'), Buffer.from(sealed.iv, 'base64'), Buffer.from(sealed.tag, 'base64'));
  const credentials = value as Partial<WooCredentials>;
  if (!credentials?.consumerKey || !credentials.consumerSecret || !credentials.webhookSecret) return null;
  return credentials as WooCredentials;
}

export function newWebhookSecret(): string {
  return randomBytes(32).toString('base64url');
}

/** What the screen may show of a key: its last four characters. */
export function maskKey(key: string): string {
  return `••••${key.slice(-4)}`;
}
